@import "tailwindcss";

/* the animatable angle behind the liquid-glass card's travelling rim —
   @property has to be declared at the top level or Tailwind drops it */
@property --orbit { syntax: "<angle>"; initial-value: 0deg; inherits: false; }
@keyframes lgc-orbit { to { --orbit: 360deg; } }

@theme {
  /* Brand typeface (Plus Jakarta Sans / JetBrains Mono), injected as CSS vars by
     next/font in app/layout.tsx.
     Mapping them here makes Tailwind's `font-sans` / `font-mono` utilities — and the
     body default below — resolve to Geist, with a graceful system fallback. */
  --font-sans: var(--font-nx-sans), ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-mono: var(--font-nx-mono), ui-monospace, "SFMono-Regular", "Menlo", monospace;

  /* Nexion's palette used to live HERE, in the bare theme — reusing
     production's own slot names (brand-*, navy-*, accent-*) plus a slate-*
     override Tailwind's stock scale never had in production at all. Since
     `@theme` custom properties cascade like any other CSS variable, that
     meant every one of the ~4,700 existing `bg-brand-500`/`text-slate-300`/
     etc. usages sitewide picked up the new values — including marketing,
     login, and admin, none of which were ever meant to change. Confirmed
     live: "buttons changed, motion graphics changed" on pages whose own
     files were byte-identical to production, because the shared color
     UNDERNEATH those unchanged files had moved.

     Fix: these slots stay at production's original values here, and the
     Nexion values move to `.nx-shell-root` below (the wrapper every
     dashboard page already renders inside, and ONLY the dashboard does) —
     the same scoping technique `.nx-dark-island` already uses successfully
     elsewhere in this file, one level up. */
  --color-brand-50: #f2f0ff;
  --color-brand-100: #e4e0ff;
  --color-brand-200: #c9c2ff;
  --color-brand-300: #a89aff;
  --color-brand-400: #8a70fb;
  --color-brand-500: #6f47f5;
  --color-brand-600: #5f2ee8;
  --color-brand-700: #5124c4;
  --color-brand-800: #421fa0;
  --color-brand-900: #371d7f;

  --color-navy-950: #060a14;
  --color-navy-900: #0a101f;
  --color-navy-850: #0d1526;
  --color-navy-800: #111a30;
  --color-navy-700: #1a2540;
  --color-navy-600: #253354;

  --color-accent-blue: #3b82f6;
  --color-accent-cyan: #22d3ee;

  /* Nexion names, for new work — these never existed in production, so
     nothing outside the dashboard can reference them; safe to leave here. */
  --color-void: #00060f;
  --color-bg: #000816;
  --color-surface: #010f22;
  --color-well: #000c1e;
  --color-hover: #021428;
  --color-side: #00081a;
  --color-rim: #002049;
  --color-rim-soft: #00173b;
  --color-rim-hi: #002a5e;
  --color-cyan: #14c5e4;
  --color-blue: #2f7eef;
  --color-violet: #8c3ae9;
  --color-magenta: #d623e1;
  --color-mint: #11c88e;
  --color-amber: #efa828;
  --color-rose: #ef426c;
  /* Nexion-only (BugReportButton, the feedback page's beta callout) — defined
     here anyway, alongside every other accent, because nothing outside the
     portal ever references it: an unused custom property has no effect on
     marketing/login/admin regardless of where it's declared. */
  --color-neon-bug: #39ff6a;

  /* slate-* is NOT overridden here on purpose — production never overrides
     it either, so this resolves to Tailwind's own stock grey scale outside
     the dashboard, exactly matching production. The Nexion blue-tinted ramp
     lives in `.nx-shell-root` below instead. */

  --color-tx: #ffffff;
  --color-tx-body: #cbdcff;
  --color-tx-mute: #93aede;
  --color-tx-dim: #7f9ad0;
  --color-tx-faint: #5f7cb4;

  --radius-card: 12px;
  --radius-nest: 8px;
  --radius-chip: 6px;

  --animate-fade-up: fade-up 0.4s ease-out both;
  --animate-pulse-dot: pulse-dot 2s ease-in-out infinite;

  /* Admin attention indicators (components/admin/AdminIndicators.tsx). `bell-shake`
     runs once whenever a new ticket / live-chat reply / email arrives; opt-in via
     `motion-safe:` at the call site so reduced-motion users just see the badge. */
  --animate-bell-shake: bell-shake 0.9s cubic-bezier(0.36, 0.07, 0.19, 0.97) both;
  @keyframes bell-shake {
    0%, 100% { transform: rotate(0); }
    10%, 50%, 90% { transform: rotate(-11deg); }
    30%, 70% { transform: rotate(11deg); }
  }

  /* Pricing explorer interactions. `price-pop` runs on every billing-cycle change
     (re-keyed number), `panel-in` on every product-tab switch. Both are opt-in via
     `motion-safe:` at the call site, so reduced-motion users see the resting frame. */
  --animate-price-pop: price-pop 0.42s cubic-bezier(0.22, 1, 0.36, 1) both;
  --animate-panel-in: panel-in 0.5s cubic-bezier(0.22, 1, 0.36, 1) both;
  /* Reverse of panel-in — used when <ChatWidget/>'s panel closes, so it settles
     away instead of just vanishing. Shorter and eased the opposite direction
     (ease-in, ends abruptly) since a close should feel snappier than an open. */
  --animate-panel-out: panel-out 0.22s cubic-bezier(0.4, 0, 1, 1) both;

  @keyframes price-pop {
    from { opacity: 0; transform: translateY(7px); filter: blur(3px); }
    to { opacity: 1; transform: translateY(0); filter: blur(0); }
  }
  @keyframes panel-in {
    from { opacity: 0; transform: translateY(12px) scale(0.994); }
    to { opacity: 1; transform: translateY(0) scale(1); }
  }
  @keyframes panel-out {
    from { opacity: 1; transform: translateY(0) scale(1); }
    to { opacity: 0; transform: translateY(10px) scale(0.98); }
  }
  /* GameHero logo entrance — a soft pop as the themed hero mounts. Applied via
     the `motion-safe:animate-gh-pop` utility so reduced-motion users see no motion. */
  @keyframes gh-pop {
    from { opacity: 0; transform: translateY(10px) scale(0.9); }
    to { opacity: 1; transform: translateY(0) scale(1); }
  }
  --animate-gh-pop: gh-pop 0.6s cubic-bezier(0.22, 1, 0.36, 1) both;

  /* Showcase mock-screen animations (marketing product pages). All are opt-in
     via Tailwind's `motion-safe:` variant, so reduced-motion users see the final
     resting state (bars full, lines visible) with no motion. */
  --animate-grow-up: grow-up 0.9s cubic-bezier(0.22, 1, 0.36, 1) both;
  --animate-grow-x: grow-x 1.1s cubic-bezier(0.22, 1, 0.36, 1) both;
  --animate-eq: eq 1.7s ease-in-out infinite;

