/* =============================================================================
   v7 — "CONSOLE".  A mixed-mode marketing concept whose subject is the product
   itself: the panel, the console, the deploy flow, rebuilt as real HTML/CSS.

   Everything here is scoped under `.v7` (the wrapper app/newwebsitev7/layout.tsx
   renders) so nothing leaks into (marketing), the portal, or the other concept
   routes sharing this checkout. The route deliberately uses NO Tailwind
   utilities — the root globals.css is a dark-first token system and this page
   goes light halfway down, so every colour here is written out explicitly and
   inherits nothing.

   THREE ENVIRONMENTS, ONE COMPONENT SET
   -------------------------------------
   The product primitives in ProductUI.tsx read only `--env-*` variables. Wrap
   the same markup in `.env-dark` and it is the real portal chrome; wrap it in
   `.env-blue` and the identical markup draws itself as a blueprint — ink
   hairlines on paper, no fills. That is what the page's dark→light seam uses:
   one panel, rendered twice, clipped down the middle. The paper environment
   itself (`.env-paper`) is the page's own voice — prose, rules, ruled tables —
   never a claim that the product ships a light theme, because it does not.
   ========================================================================== */

.v7 {
  /* ---- dark half: the portal's REAL token values (app/globals.css) ---- */
  --v7-void: #00060f;
  --v7-deep: #000816;
  --v7-surface: #010f22;
  --v7-well: #000c1e;
  --v7-rim: #002049;
  --v7-rim-hi: #002a5e;
  --v7-cyan: #14c5e4;
  --v7-blue: #2f7eef;
  --v7-violet: #8c3ae9;
  --v7-mint: #11c88e;
  --v7-amber: #efa828;
  --v7-tx: #ffffff;
  --v7-tx-2: #cbdcff;
  --v7-tx-3: #93aede;
  --v7-tx-4: #5f7cb4;

  /* ---- light half: a designed paper palette, not an inversion ----
     Warm bone ground + cold ink + the brand ramp pulled down in luminance so
     it survives on paper (cyan #14c5e4 is unreadable on bone; its paper
     counterpart is a deep teal). The warmth belongs to the ENVIRONMENT, not
     to the brand — no warm accents anywhere, so navy/violet/cyan stays the
     only accent family on the page. */
  --v7-paper: #f3f0e9;
  --v7-paper-raised: #fbfaf6;
  --v7-paper-cool: #e8ecf3;
  --v7-ink: #101520;
  --v7-ink-2: #3d4653;
  --v7-ink-3: #6c7683;
  --v7-rule: #ded6c6;
  --v7-rule-soft: #ebe5d8;
  --v7-rule-cool: #ccd6e6;
  --v7-deep-blue: #1a4bb8;
  --v7-deep-violet: #5b1fae;
  --v7-deep-magenta: #b8155f;
  --v7-deep-teal: #0f6f8c;
  --v7-ink-mint: #0a7a57;

  --v7-sans: var(--font-v7-sans), "Helvetica Neue", Arial, sans-serif;
  --v7-mono: var(--font-v7-mono), ui-monospace, "SFMono-Regular", Menlo, monospace;

  /* body in globals.css paints a fixed dark radial wash; every section below
     is opaque, and this backstop covers any sub-pixel gap between them. */
  background-color: var(--v7-void);
  color: var(--v7-tx-2);
  font-family: var(--v7-sans);
  font-size: 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  overflow-x: clip;
}

.v7 *::selection { background: #2f7eef44; }

/* =============================================================================
   ENVIRONMENTS
   ========================================================================== */

.v7 .env-dark {
  --env-bg: var(--v7-void);
  --env-panel: linear-gradient(180deg, #021530 0%, #010f22 42%, #010c1d 100%);
  --env-head: #00122a;
  --env-well: #00091a;
  --env-row: #00102450;
  --env-rim: var(--v7-rim);
  --env-rim-hi: var(--v7-rim-hi);
  --env-tx: var(--v7-tx);
  --env-tx-2: var(--v7-tx-2);
  --env-tx-3: var(--v7-tx-3);
  --env-tx-4: var(--v7-tx-4);
  --env-accent: var(--v7-blue);
  --env-accent-2: var(--v7-cyan);
  --env-ok: var(--v7-mint);
  --env-warn: var(--v7-amber);
  --env-shadow: 0 34px 90px -34px #000000, 0 0 0 1px #00204930;
  --env-dot-bg: currentColor;
  --env-dot-ring: 0 0 0 0 transparent;
  --env-chip: #00142e;
  --env-radius: 14px;
}

/* The blueprint: the SAME panel markup, drawn instead of rendered. Fills go
   transparent, every border becomes an ink hairline, status dots become rings.
   Used below the seam so the transition reads as "the screen becomes the
   spec" rather than "someone recoloured the UI". */
.v7 .env-blue {
  --env-bg: var(--v7-paper);
  --env-panel: transparent;
  --env-head: transparent;
  --env-well: rgba(26, 75, 184, 0.045);
  --env-row: transparent;
  --env-rim: rgba(26, 75, 184, 0.42);
  --env-rim-hi: rgba(26, 75, 184, 0.62);
  --env-tx: #16327a;
  --env-tx-2: rgba(22, 50, 122, 0.88);
  --env-tx-3: rgba(22, 50, 122, 0.62);
  --env-tx-4: rgba(22, 50, 122, 0.42);
  --env-accent: var(--v7-deep-blue);
  --env-accent-2: var(--v7-deep-teal);
  --env-ok: var(--v7-ink-mint);
  --env-warn: #8a5a08;
  --env-shadow: none;
  --env-dot-bg: transparent;
  --env-dot-ring: inset 0 0 0 1px currentColor;
  --env-chip: transparent;
  --env-radius: 14px;
}

/* =============================================================================
   LAYOUT PRIMITIVES
   ========================================================================== */

.v7 .wrap { width: 100%; max-width: 1180px; margin: 0 auto; padding: 0 20px; }
.v7 .sec { position: relative; }

/* The spine: one continuous hairline down the left gutter, changing MATERIAL at
   the seam (lit in the dark half, printed in the light half) so the two
   environments are visibly one page. Only drawn when there is real gutter to
   draw it in. */
@media (min-width: 1360px) {
  .v7 .sec::before {
    content: "";
    position: absolute;
    top: 0;
    bottom: 0;
    left: calc(50% - 634px);
    width: 1px;
    background: var(--v7-spine, #00234f);
    pointer-events: none;
  }
  .v7 .sec-paper { --v7-spine: #ded6c6; }
  .v7 .sec-cool { --v7-spine: #ccd6e6; }
}

.v7 .eyebrow {
  font-family: var(--v7-mono);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  margin: 0 0 18px;
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--v7-tx-3);
}
.v7 .eyebrow b { font-weight: 700; color: var(--v7-cyan); }
.v7 .eyebrow i { flex: 1; height: 1px; background: #00234f; font-style: normal; max-width: 120px; }
.v7 .sec-paper .eyebrow, .v7 .sec-cool .eyebrow { color: var(--v7-ink-3); }
.v7 .sec-paper .eyebrow b, .v7 .sec-cool .eyebrow b { color: var(--v7-deep-blue); }
.v7 .sec-paper .eyebrow i { background: var(--v7-rule); }
.v7 .sec-cool .eyebrow i { background: var(--v7-rule-cool); }

.v7 h1, .v7 h2, .v7 h3, .v7 h4 { font-family: var(--v7-sans); margin: 0; }

.v7 .h1 {
  font-size: clamp(2.6rem, 6.1vw, 5.05rem);
  font-weight: 900;
  line-height: 0.94;
  letter-spacing: -0.038em;
  color: var(--v7-tx);
}
.v7 .h2 {
  font-size: clamp(1.85rem, 3.5vw, 2.9rem);
  font-weight: 700;
  line-height: 1.04;
  letter-spacing: -0.028em;
  color: var(--v7-tx);
}
.v7 .sec-paper .h2, .v7 .sec-cool .h2 { color: var(--v7-ink); }
.v7 .h3 {
  font-size: 1.0625rem;
  font-weight: 700;
  letter-spacing: -0.012em;
  line-height: 1.3;
  color: var(--v7-tx);
}
.v7 .sec-paper .h3, .v7 .sec-cool .h3 { color: var(--v7-ink); }

.v7 .grad {
  background: linear-gradient(94deg, #4b92ff 0%, #14c5e4 34%, #8c3ae9 82%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.v7 .lede {
  font-size: 1.0625rem;
  line-height: 1.66;
  color: var(--v7-tx-2);
  margin: 18px 0 0;
  max-width: 54ch;
}
.v7 .sec-paper .lede, .v7 .sec-cool .lede { color: var(--v7-ink-2); }
.v7 .note {
  font-family: var(--v7-mono);
  font-size: 10.5px;
  line-height: 1.7;
  letter-spacing: 0.01em;
  color: var(--v7-tx-4);
}
.v7 .sec-paper .note, .v7 .sec-cool .note { color: var(--v7-ink-3); }

/* ---- buttons ---- */
.v7 .btn {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 13px 20px;
  border-radius: 10px;
  font-size: 0.9375rem;
  font-weight: 600;
  letter-spacing: -0.008em;
  text-decoration: none;
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform 0.16s ease, box-shadow 0.16s ease, background 0.16s ease, border-color 0.16s ease;
}
.v7 .btn-primary {
  background: linear-gradient(100deg, #2f7eef, #8c3ae9);
  color: #fff;
  box-shadow: 0 12px 30px -12px #2f7eefaa, inset 0 1px 0 #ffffff33;
}
.v7 .btn-ghost {
  background: #00142e88;
  border-color: #00295e;
  color: var(--v7-tx-2);
}
.v7 .btn-ghost:hover { border-color: #0a3f86; color: #fff; }
.v7 .btn-ink {
  background: var(--v7-ink);
  color: var(--v7-paper-raised);
  box-shadow: 0 10px 26px -14px #10152088;
}
.v7 .btn-paper {
  background: transparent;
  border-color: var(--v7-rule);
  color: var(--v7-ink);
}
.v7 .btn-paper:hover { border-color: var(--v7-deep-blue); color: var(--v7-deep-blue); }
.v7 .btn:hover { transform: translateY(-1px); }
.v7 .btn:active { transform: translateY(0); }

/* =============================================================================
   PRODUCT PRIMITIVES  (ProductUI.tsx — env-driven, used in all three modes)
   ========================================================================== */

.v7 .pnl {
  background: var(--env-panel);
  border: 1px solid var(--env-rim);
  border-radius: var(--env-radius);
  box-shadow: var(--env-shadow);
  color: var(--env-tx-2);
  overflow: hidden;
}
.v7 .env-blue .pnl { background: transparent; }

.v7 .pnl-head {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 13px;
  background: var(--env-head);
  border-bottom: 1px solid var(--env-rim);
  min-height: 46px;
}
.v7 .pnl-mark { width: 18px; height: 18px; object-fit: contain; flex: none; opacity: 0.95; }
.v7 .env-blue .pnl-mark { opacity: 0.5; filter: grayscale(1) brightness(0.55); }
.v7 .pnl-name {
  font-family: var(--v7-mono);
  font-size: 11.5px;
  font-weight: 500;
  letter-spacing: -0.02em;
  color: var(--env-tx);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.v7 .pnl-spacer { flex: 1; min-width: 6px; }

.v7 .pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-family: var(--v7-mono);
  font-size: 9.5px;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 4px 9px 4px 7px;
  border-radius: 99px;
  border: 1px solid var(--env-rim);
  background: var(--env-chip);
  white-space: nowrap;
}
.v7 .pill-ok { color: var(--env-ok); border-color: color-mix(in srgb, var(--env-ok) 42%, transparent); }
.v7 .pill-work { color: var(--env-warn); border-color: color-mix(in srgb, var(--env-warn) 42%, transparent); }
.v7 .pill-idle { color: var(--env-tx-3); }
.v7 .pill-info { color: var(--env-accent-2); border-color: color-mix(in srgb, var(--env-accent-2) 42%, transparent); }

.v7 .dot {
  width: 6px;
  height: 6px;
  border-radius: 99px;
  background: var(--env-dot-bg);
  box-shadow: var(--env-dot-ring);
  flex: none;
}
.v7 .dot-pulse { animation: v7-pulse 2.1s ease-in-out infinite; }

/* tab strip inside the product chrome */
.v7 .tabs { display: flex; gap: 2px; }
.v7 .tab {
  font-family: var(--v7-mono);
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 6px 10px;
  border-radius: 7px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--env-tx-4);
  cursor: default;
  white-space: nowrap;
}
.v7 .tab-on {
  color: var(--env-tx);
  background: color-mix(in srgb, var(--env-accent) 16%, transparent);
  border-color: color-mix(in srgb, var(--env-accent) 44%, transparent);
}

/* spec strip: vCPU / RAM / disk / transfer */
.v7 .spec {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  border-bottom: 1px solid var(--env-rim);
}
.v7 .spec > div { padding: 11px 13px; border-right: 1px solid var(--env-rim); }
.v7 .spec > div:last-child { border-right: 0; }
.v7 .spec dt {
  font-family: var(--v7-mono);
  font-size: 8.5px;
  letter-spacing: 0.17em;
  text-transform: uppercase;
  color: var(--env-tx-4);
  margin: 0 0 4px;
}
.v7 .spec dd {
  margin: 0;
  font-family: var(--v7-mono);
  font-size: 12.5px;
  font-weight: 500;
  letter-spacing: -0.03em;
  color: var(--env-tx);
}

/* the console well */
.v7 .well {
  background: var(--env-well);
  border-top: 1px solid var(--env-rim);
  padding: 14px 15px 16px;
  font-family: var(--v7-mono);
  font-size: 11px;
  line-height: 1.95;
  letter-spacing: -0.03em;
  overflow: hidden;
}
.v7 .well-tall { min-height: 214px; }
.v7 .ln { display: flex; gap: 8px; align-items: baseline; white-space: pre-wrap; word-break: break-word; }
.v7 .ln-k { color: var(--env-tx-4); flex: none; width: 4.6em; }
.v7 .ln-cmd { color: var(--env-accent-2); }
.v7 .ln-out { color: var(--env-tx-2); }
.v7 .ln-ok { color: var(--env-ok); }
.v7 .ln-note { color: var(--env-tx-4); }
.v7 .caret {
  display: inline-block;
  width: 7px;
  height: 13px;
  translate: 0 2px;
  background: var(--env-accent-2);
  animation: v7-caret 1.1s steps(1, end) infinite;
}

/* generic data rows (files, network, images) */
.v7 .rows { display: grid; }
.v7 .row {
  display: grid;
  align-items: center;
  gap: 12px;
  padding: 9px 13px;
  border-bottom: 1px solid var(--env-rim);
  font-family: var(--v7-mono);
  font-size: 11px;
  letter-spacing: -0.025em;
  color: var(--env-tx-2);
}
.v7 .row:last-child { border-bottom: 0; }
.v7 .row-head {
  background: var(--env-row);
  font-size: 8.5px;
  letter-spacing: 0.17em;
  text-transform: uppercase;
  color: var(--env-tx-4);
}
.v7 .row-file { grid-template-columns: 18px minmax(0, 1fr) 62px 86px; }
.v7 .row-net { grid-template-columns: minmax(0, 1fr) minmax(0, 1.25fr) 78px; }
.v7 .row-b { color: var(--env-tx); }
.v7 .row-r { text-align: right; }
.v7 .row ins { text-decoration: none; color: var(--env-tx-4); }
.v7 .glyph { color: var(--env-tx-4); display: flex; }

/* metrics — the EMPTY state on purpose (see ProductUI.tsx) */
.v7 .metrics { padding: 15px 15px 12px; border-top: 1px solid var(--env-rim); }
.v7 .metrics-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 12px;
}
.v7 .metrics-plot {
  position: relative;
  height: 128px;
  border-left: 1px solid var(--env-rim);
  border-bottom: 1px solid var(--env-rim);
  background-image: repeating-linear-gradient(to top, var(--env-rim) 0 1px, transparent 1px 32px);
  display: grid;
  place-items: center;
}
.v7 .metrics-empty {
  font-family: var(--v7-mono);
  font-size: 10px;
  letter-spacing: 0.04em;
  text-align: center;
  color: var(--env-tx-4);
  padding: 0 16px;
  max-width: 34ch;
  line-height: 1.8;
}
.v7 .metrics-x {
  display: flex;
  justify-content: space-between;
  font-family: var(--v7-mono);
  font-size: 8.5px;
  letter-spacing: 0.12em;
  color: var(--env-tx-4);
  padding: 7px 0 0 4px;
}

/* picker view (deploy step 01) */
.v7 .pick { padding: 13px; display: grid; gap: 12px; }
.v7 .pick-label {
  font-family: var(--v7-mono);
  font-size: 8.5px;
  letter-spacing: 0.17em;
  text-transform: uppercase;
  color: var(--env-tx-4);
  margin-bottom: 7px;
}
.v7 .pick-opts { display: flex; flex-wrap: wrap; gap: 7px; }
.v7 .opt {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 11px;
  border-radius: 9px;
  border: 1px solid var(--env-rim);
  background: var(--env-chip);
  font-family: var(--v7-mono);
  font-size: 10.5px;
  letter-spacing: -0.02em;
  color: var(--env-tx-3);
}
.v7 .opt-on {
  color: var(--env-tx);
  border-color: color-mix(in srgb, var(--env-accent) 62%, transparent);
  background: color-mix(in srgb, var(--env-accent) 18%, transparent);
}
.v7 .opt img { width: 13px; height: 13px; object-fit: contain; }
.v7 .env-blue .opt img { filter: grayscale(1) opacity(0.55); }
.v7 .opt small { color: var(--env-tx-4); font-size: 9.5px; }
.v7 .opt-on small { color: var(--env-tx-3); }

/* blueprint-only ornament: corner crosshairs + a dashed measure baseline, so
   the lower half of the seam panel reads as a technical drawing. */
.v7 .env-blue .pnl { position: relative; }
.v7 .env-blue .pnl::before,
.v7 .env-blue .pnl::after {
  content: "";
  position: absolute;
  width: 13px;
  height: 13px;
  border: 0 solid rgba(26, 75, 184, 0.5);
  pointer-events: none;
}
.v7 .env-blue .pnl::before { left: -7px; bottom: -7px; border-left-width: 1px; border-bottom-width: 1px; }
.v7 .env-blue .pnl::after { right: -7px; bottom: -7px; border-right-width: 1px; border-bottom-width: 1px; }

/* =============================================================================
   01 — HERO  (dark, cinematic)
   ========================================================================== */

.v7 .hero {
  background: linear-gradient(180deg, #00060f 0%, #00081a 46%, #00060f 100%);
  padding-bottom: 96px;
  isolation: isolate;
}
.v7 .hero-sky {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse 58% 52% at 80% 4%, rgba(140, 58, 233, 0.32), transparent 66%),
    radial-gradient(ellipse 66% 58% at 20% -4%, rgba(47, 126, 239, 0.22), transparent 62%),
    radial-gradient(ellipse 100% 44% at 52% 104%, rgba(20, 197, 228, 0.09), transparent 70%);
}
.v7 .hero-grid {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background-image:
    linear-gradient(to right, rgba(0, 40, 92, 0.6) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(0, 40, 92, 0.6) 1px, transparent 1px);
  background-size: 68px 68px;
  -webkit-mask-image: radial-gradient(ellipse 78% 68% at 60% 34%, #000 0%, transparent 74%);
  mask-image: radial-gradient(ellipse 78% 68% at 60% 34%, #000 0%, transparent 74%);
}
.v7 .hero > .wrap { position: relative; z-index: 1; }

/* nav */
.v7 .nav {
  display: flex;
  align-items: center;
  gap: 22px;
  padding: 22px 0 8px;
}
.v7 .nav-logo { display: flex; align-items: center; gap: 10px; text-decoration: none; }
.v7 .nav-logo img { height: 25px; width: auto; }
.v7 .nav-links { display: none; gap: 4px; flex: 1; }
.v7 .nav-links a {
  font-size: 0.8125rem;
  font-weight: 500;
  letter-spacing: -0.006em;
  color: var(--v7-tx-3);
  text-decoration: none;
  padding: 8px 11px;
  border-radius: 8px;
}
.v7 .nav-links a:hover { color: #fff; background: #00142e; }
.v7 .nav-cta { margin-left: auto; display: flex; align-items: center; gap: 8px; }
.v7 .nav-cta .btn { padding: 9px 15px; font-size: 0.8125rem; }
@media (min-width: 900px) { .v7 .nav-links { display: flex; } .v7 .nav-cta { margin-left: 0; } }

.v7 .hero-body {
  display: grid;
  gap: 44px;
  padding-top: clamp(40px, 6vw, 74px);
  align-items: start;
}
@media (min-width: 1080px) {
  .v7 .hero-body { grid-template-columns: minmax(0, 0.86fr) minmax(0, 1.14fr); gap: 52px; }
}

.v7 .hero-cta { display: flex; flex-wrap: wrap; gap: 11px; margin-top: 30px; }

/* the real-numbers strip under the headline */
.v7 .facts {
  list-style: none;
  margin: 38px 0 0;
  padding: 20px 0 0;
  border-top: 1px solid #00203f;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px 20px;
}
@media (min-width: 620px) { .v7 .facts { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
.v7 .facts b {
  display: block;
  font-family: var(--v7-mono);
  font-size: 1.28rem;
  font-weight: 700;
  letter-spacing: -0.06em;
  color: #fff;
  line-height: 1;
}
.v7 .facts span {
  display: block;
  margin-top: 7px;
  font-size: 0.75rem;
  line-height: 1.45;
  color: var(--v7-tx-4);
}

/* staged product composition */
.v7 .stage { position: relative; }
.v7 .stage-main { position: relative; z-index: 2; }
.v7 .stage-sat { display: none; }
@media (min-width: 1080px) {
  .v7 .stage { padding: 0 0 62px 54px; }
  .v7 .stage-sat {
    display: block;
    position: absolute;
    z-index: 3;
    width: 268px;
  }
  .v7 .stage-sat-a { left: -46px; bottom: 0; }
  .v7 .stage-sat-b { right: -22px; top: -30px; width: 232px; }
}
.v7 .stage-glow {
  position: absolute;
  z-index: 1;
  inset: 8% -12% -6% 6%;
  background: radial-gradient(ellipse at 50% 50%, rgba(47, 126, 239, 0.3), transparent 68%);
  filter: blur(26px);
  pointer-events: none;
}

.v7 .mini {
  background: linear-gradient(180deg, #03193a, #010f22);
  border: 1px solid #00295e;
  border-radius: 12px;
  box-shadow: 0 26px 60px -26px #000, 0 0 0 1px #0a2a5a33;
  overflow: hidden;
}
.v7 .mini-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 12px;
  border-bottom: 1px solid #00224d;
  font-family: var(--v7-mono);
  font-size: 9.5px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--v7-tx-4);
}

/* =============================================================================
   02 — DEPLOY SEQUENCE  (dark; the page's one big moment)
   ========================================================================== */

.v7 .seq {
  background: linear-gradient(180deg, #00060f 0%, #00050d 70%, #00060f 100%);
  padding: clamp(64px, 8vw, 104px) 0 clamp(56px, 7vw, 92px);
  border-top: 1px solid #00182f;
}
.v7 .seq-top { max-width: 760px; }
.v7 .seq-ctl {
  margin-top: 30px;
  border: 1px solid #00224d;
  border-radius: 14px;
  background: #00091c;
  padding: 15px 16px;
  display: grid;
  gap: 14px;
}
@media (min-width: 760px) { .v7 .seq-ctl { grid-template-columns: auto auto 1fr; align-items: end; gap: 26px; } }
.v7 .ctl-group { min-width: 0; }
.v7 .ctl-label {
  font-family: var(--v7-mono);
  font-size: 8.5px;
  letter-spacing: 0.19em;
  text-transform: uppercase;
  color: var(--v7-tx-4);
  margin-bottom: 8px;
}
.v7 .ctl-opts { display: flex; flex-wrap: wrap; gap: 6px; }
.v7 .chip {
  font-family: var(--v7-mono);
  font-size: 10.5px;
  letter-spacing: -0.02em;
  padding: 7px 11px;
  border-radius: 8px;
  border: 1px solid #00295e;
  background: #00132c;
  color: var(--v7-tx-3);
  cursor: pointer;
  transition: border-color 0.14s ease, color 0.14s ease, background 0.14s ease;
}
.v7 .chip:hover { color: #fff; border-color: #0b4694; }
.v7 .chip-on {
  color: #fff;
  border-color: #2f7eef;
  background: linear-gradient(180deg, #123a7d, #0a2455);
  box-shadow: inset 0 1px 0 #ffffff1f;
}
.v7 .chip small { color: inherit; opacity: 0.6; margin-left: 5px; }
.v7 .ctl-replay { display: flex; justify-content: flex-start; }
@media (min-width: 760px) { .v7 .ctl-replay { justify-content: flex-end; } }
.v7 .replay {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--v7-mono);
  font-size: 10px;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  padding: 9px 14px;
  border-radius: 9px;
  border: 1px solid #00356f;
  background: #000d20;
  color: var(--v7-cyan);
  cursor: pointer;
}
.v7 .replay:hover { border-color: #14c5e4; background: #001527; }

/* the sequence grid */
.v7 .dseq { margin-top: 40px; display: grid; grid-template-columns: minmax(0, 1fr); gap: 22px; }
@media (min-width: 1024px) {
  .v7 .dseq { grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr); gap: 54px; align-items: start; }
}
/* mobile / at-rest: interleave step text with its own panel, no duplicated DOM */
@media (max-width: 1023px) {
  .v7 .dseq-rail, .v7 .dseq-stage { display: contents; }
  .v7 .dstep:nth-child(1) { order: 1; }
  .v7 .dslide:nth-child(1) { order: 2; }
  .v7 .dstep:nth-child(2) { order: 3; }
  .v7 .dslide:nth-child(2) { order: 4; }
  .v7 .dstep:nth-child(3) { order: 5; }
  .v7 .dslide:nth-child(3) { order: 6; }
  .v7 .dstep:nth-child(4) { order: 7; }
  .v7 .dslide:nth-child(4) { order: 8; }
  .v7 .dstep { padding-bottom: 4px; }
}

.v7 .dseq-rail { display: grid; gap: 8px; }
.v7 .dstep {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  gap: 16px;
  padding: 18px 0;
}
@media (min-width: 1024px) { .v7 .dstep { min-height: 62vh; align-content: center; padding: 30px 0; } }
.v7 .dstep-num { position: relative; }
.v7 .dstep-num span {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 9px;
  border: 1px solid #00295e;
  background: #000d20;
  font-family: var(--v7-mono);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: -0.04em;
  color: var(--v7-tx-4);
  transition: color 0.3s ease, border-color 0.3s ease, background 0.3s ease, box-shadow 0.3s ease;
}
.v7 .dstep-num::after {
  content: "";
  position: absolute;
  left: 17px;
  top: 40px;
  bottom: -30px;
  width: 1px;
  background: #00224d;
}
.v7 .dstep:last-child .dstep-num::after { display: none; }
.v7 .dstep-on .dstep-num span {
  color: #fff;
  border-color: #2f7eef;
  background: linear-gradient(180deg, #16407f, #0a2352);
  box-shadow: 0 0 0 4px #2f7eef1f, 0 8px 22px -12px #2f7eefaa;
}
.v7 .dstep-done .dstep-num span { color: var(--v7-mint); border-color: #0a5c46; }
.v7 .dstep h3 { transition: color 0.3s ease; }
.v7 .dstep-body { color: var(--v7-tx-3); font-size: 0.9375rem; line-height: 1.68; margin: 9px 0 0; max-width: 46ch; }
.v7 .dstep-meta {
  margin: 14px 0 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.v7 .dstep-meta li {
  font-family: var(--v7-mono);
  font-size: 9.5px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--v7-tx-4);
  border: 1px solid #001c3d;
  border-radius: 6px;
  padding: 4px 8px;
}
.v7 .dstep:not(.dstep-on):not(.dstep-done) h3 { color: #a9c3ee; }

.v7 .dseq-stage { display: grid; gap: 20px; }
@media (min-width: 1024px) {
  .v7 .dseq.is-live .dseq-stage { position: sticky; top: 76px; display: block; }
  .v7 .dseq.is-live .dslide { display: none; }
  .v7 .dseq.is-live .dslide-on { display: block; }
}
.v7 .dslide-cap {
  margin: 11px 2px 0;
  font-family: var(--v7-mono);
  font-size: 9.5px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--v7-tx-4);
  display: flex;
  gap: 10px;
  align-items: center;
}
.v7 .seq-foot { margin-top: 34px; border-top: 1px solid #00182f; padding-top: 16px; max-width: 78ch; }

/* =============================================================================
   THE SEAM  — dark half meets light half
   ========================================================================== */

.v7 .seam { position: relative; }
.v7 .seam-sky {
  height: clamp(150px, 19vw, 230px);
  background: linear-gradient(
    180deg,
    #00060f 0%,
    #00081e 26%,
    #120c46 48%,
    #3a1c9e 66%,
    #2f7eef 84%,
    #8fdcf1 99%,
    #cdeefa 100%
  );
}
.v7 .seam-band {
  position: relative;
  --seam: 50%;
  padding: clamp(28px, 4vw, 52px) 0;
  /* ONE variable drives both the panel's clip line and the page's mode change,
     so the seam can never drift out of alignment with the split panel. The
     stop is HARD on purpose — a soft blend between navy and bone goes muddy
     grey and reads as an accident. */
  background: linear-gradient(
    180deg,
    #cdeefa 0%,
    #7fd4ee 5%,
    #2f7eef 22%,
    #16308a 42%,
    #061634 calc(var(--seam) - 2px),
    #ffffff calc(var(--seam) - 2px) var(--seam),
    var(--v7-paper) var(--seam) 100%
  );
}
.v7 .seam-rule {
  position: absolute;
  left: 0;
  right: 0;
  top: calc(var(--seam) - 1px);
  height: 1px;
  background: linear-gradient(90deg, transparent, #bfe8ff 18%, #ffffff 50%, #bfe8ff 82%, transparent);
  box-shadow: 0 -2px 26px 2px rgba(80, 180, 255, 0.5), 0 -1px 70px 8px rgba(47, 126, 239, 0.34);
  pointer-events: none;
}
/* the printed echo of the lit line, 7px below it on the paper side — same
   geometry, different material. */
.v7 .seam-echo {
  position: absolute;
  left: 0;
  right: 0;
  top: calc(var(--seam) + 7px);
  height: 1px;
  background: var(--v7-rule);
  pointer-events: none;
}
.v7 .seam-tag {
  position: absolute;
  top: calc(var(--seam) - 26px);
  left: 0;
  right: 0;
  display: flex;
  justify-content: center;
  pointer-events: none;
}
.v7 .seam-tag span {
  font-family: var(--v7-mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: #eaf7ff;
  text-shadow: 0 0 18px rgba(47, 126, 239, 0.9);
}

/* the split panel: identical markup, two environments, clipped on --seam */
.v7 .split { position: relative; --seam: 50%; }
.v7 .split-copy { position: relative; }
.v7 .split-a { clip-path: inset(0 0 calc(100% - var(--seam)) 0); }
.v7 .split-b {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  clip-path: inset(var(--seam) 0 0 0);
}
.v7 .seam-caption {
  position: relative;
  z-index: 2;
  margin: clamp(26px, 3.4vw, 44px) auto 0;
  max-width: 62ch;
  text-align: center;
}
.v7 .seam-caption p {
  margin: 0;
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--v7-ink-2);
}
.v7 .seam-caption b { color: var(--v7-ink); font-weight: 700; }
.v7 .seam-caption .note { display: block; margin-top: 12px; color: var(--v7-ink-3); }

/* =============================================================================
   LIGHT HALF
   ========================================================================== */

.v7 .sec-paper {
  background-color: var(--v7-paper);
  /* faint engineering-paper rule grid; the light half is a spec sheet, not a
     white marketing page */
  background-image:
    linear-gradient(to right, rgba(16, 21, 32, 0.035) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(16, 21, 32, 0.035) 1px, transparent 1px);
  background-size: 34px 34px;
  color: var(--v7-ink-2);
  padding: clamp(60px, 7.5vw, 104px) 0;
}
.v7 .sec-cool {
  background-color: var(--v7-paper-cool);
  background-image:
    linear-gradient(to right, rgba(16, 32, 64, 0.045) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(16, 32, 64, 0.045) 1px, transparent 1px);
  background-size: 34px 34px;
  color: var(--v7-ink-2);
  padding: clamp(60px, 7.5vw, 104px) 0;
  border-top: 1px solid var(--v7-rule);
  border-bottom: 1px solid var(--v7-rule);
}

.v7 .two {
  display: grid;
  gap: 40px;
  align-items: start;
}
@media (min-width: 1024px) {
  .v7 .two { grid-template-columns: minmax(0, 0.82fr) minmax(0, 1.18fr); gap: 56px; }
}

/* blueprint annotation list */
.v7 .annot { list-style: none; margin: 30px 0 0; padding: 0; display: grid; align-content: start; }
.v7 .annot li {
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr);
  gap: 14px;
  padding: 17px 0;
  border-top: 1px solid var(--v7-rule);
}
.v7 .annot li:last-child { border-bottom: 1px solid var(--v7-rule); }
.v7 .annot-ico {
  width: 30px;
  height: 30px;
  border: 1px solid var(--v7-rule);
  border-radius: 8px;
  display: grid;
  place-items: center;
  color: var(--v7-deep-blue);
  background: var(--v7-paper-raised);
}
.v7 .annot h4 {
  font-size: 0.9375rem;
  font-weight: 700;
  letter-spacing: -0.012em;
  color: var(--v7-ink);
  margin: 0 0 5px;
}
.v7 .annot p { margin: 0; font-size: 0.875rem; line-height: 1.62; color: var(--v7-ink-2); }
.v7 .annot code {
  font-family: var(--v7-mono);
  font-size: 10px;
  letter-spacing: -0.02em;
  color: var(--v7-deep-blue);
}

/* a dark product island mounted on paper */
.v7 .island { position: relative; }
.v7 .island-mount {
  border: 1px solid var(--v7-rule);
  border-radius: 20px;
  background: var(--v7-paper-raised);
  padding: 13px;
  box-shadow: 0 22px 46px -30px rgba(70, 60, 40, 0.42);
}
.v7 .island-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  padding: 2px 3px 13px;
}
.v7 .island-bar .ib-label {
  font-family: var(--v7-mono);
  font-size: 8.5px;
  letter-spacing: 0.19em;
  text-transform: uppercase;
  color: var(--v7-ink-3);
  margin-right: 2px;
}
.v7 .ptab {
  font-family: var(--v7-mono);
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 7px 11px;
  border-radius: 8px;
  border: 1px solid var(--v7-rule);
  background: transparent;
  color: var(--v7-ink-3);
  cursor: pointer;
  transition: color 0.14s ease, border-color 0.14s ease, background 0.14s ease;
}
.v7 .ptab:hover { color: var(--v7-ink); border-color: var(--v7-ink-3); }
.v7 .ptab-on {
  color: var(--v7-paper-raised);
  background: var(--v7-ink);
  border-color: var(--v7-ink);
}
.v7 .island-cap {
  margin: 12px 3px 0;
  font-family: var(--v7-mono);
  font-size: 9.5px;
  line-height: 1.7;
  letter-spacing: 0.02em;
  color: var(--v7-ink-3);
}

/* one-click image catalogue strip */
.v7 .cat { margin-top: clamp(44px, 5vw, 64px); border-top: 1px solid var(--v7-rule); padding-top: 26px; }
.v7 .cat-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 10px 22px; }
.v7 .cat-head h3 { font-size: 1.125rem; }
.v7 .cat-counts { display: flex; flex-wrap: wrap; gap: 16px; margin-left: auto; }
.v7 .cat-counts span {
  font-family: var(--v7-mono);
  font-size: 10px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--v7-ink-3);
}
.v7 .cat-counts b { color: var(--v7-ink); font-weight: 700; }
.v7 .cat-grid {
  margin-top: 22px;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(124px, 1fr));
  gap: 1px;
  background: var(--v7-rule);
  border: 1px solid var(--v7-rule);
  border-radius: 12px;
  overflow: hidden;
}
.v7 .cat-cell {
  background: var(--v7-paper-raised);
  padding: 15px 13px;
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.v7 .cat-cell img { width: 20px; height: 20px; object-fit: contain; flex: none; }
.v7 .cat-cell span {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: -0.008em;
  color: var(--v7-ink);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---- ruled spec / price table ---- */
.v7 .table-scroll { overflow-x: auto; margin-top: 34px; }
.v7 .tbl { width: 100%; border-collapse: collapse; min-width: 700px; }
.v7 .tbl caption { caption-side: bottom; text-align: left; padding-top: 14px; }
.v7 .tbl th, .v7 .tbl td { text-align: left; padding: 15px 16px 14px; border-bottom: 1px solid var(--v7-rule-cool); }
.v7 .tbl thead th {
  font-family: var(--v7-mono);
  font-size: 8.5px;
  font-weight: 500;
  letter-spacing: 0.19em;
  text-transform: uppercase;
  color: var(--v7-ink-3);
  border-bottom-color: var(--v7-ink);
  padding-bottom: 10px;
}
.v7 .tbl tbody th {
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: -0.015em;
  color: var(--v7-ink);
  white-space: nowrap;
}
.v7 .tbl td {
  font-family: var(--v7-mono);
  font-size: 12px;
  letter-spacing: -0.03em;
  color: var(--v7-ink-2);
  white-space: nowrap;
}
.v7 .tbl .price { color: var(--v7-ink); font-weight: 700; font-size: 13.5px; }
.v7 .tbl .renew { color: var(--v7-ink-3); font-size: 10.5px; display: block; margin-top: 4px; letter-spacing: 0.01em; }
.v7 .tbl tbody tr:hover td, .v7 .tbl tbody tr:hover th { background: rgba(26, 75, 184, 0.045); }
.v7 .tbl-go { text-align: right; }
.v7 .tbl-go a {
  font-family: var(--v7-mono);
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--v7-deep-blue);
  text-decoration: none;
  border-bottom: 1px solid rgba(26, 75, 184, 0.35);
  padding-bottom: 2px;
}
.v7 .tbl-go a:hover { border-bottom-color: var(--v7-deep-blue); }

.v7 .region-pair { display: grid; gap: 1px; margin-top: 34px; background: var(--v7-rule-cool); border: 1px solid var(--v7-rule-cool); border-radius: 12px; overflow: hidden; }
@media (min-width: 620px) { .v7 .region-pair { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.v7 .region {
  background: var(--v7-paper-raised);
  padding: 20px;
  display: grid;
  gap: 6px;
}
.v7 .region-code {
  font-family: var(--v7-mono);
  font-size: 9.5px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--v7-deep-blue);
}
.v7 .region-name { font-size: 1.25rem; font-weight: 700; letter-spacing: -0.02em; color: var(--v7-ink); }
.v7 .region p { margin: 0; font-size: 0.8125rem; line-height: 1.6; color: var(--v7-ink-2); }

.v7 .flags { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 30px; padding: 0; list-style: none; }
.v7 .flags li {
