.v7 .foot-links a:hover { color: var(--v7-deep-blue); }
.v7 .foot-note { margin-left: auto; }

/* =============================================================================
   MOTION — every animation below is opt-in. Base CSS is always the RESTING,
   fully-legible state: nothing on this page waits at opacity 0 for an
   observer, and reduced-motion users get the finished frame plus the plain
   stacked (non-sticky) deploy sequence.
   ========================================================================== */

@keyframes v7-caret { 0%, 49% { opacity: 1; } 50%, 100% { opacity: 0; } }
@keyframes v7-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.35; } }
@keyframes v7-line-in { from { opacity: 0; transform: translateY(5px); } to { opacity: 1; transform: none; } }
@keyframes v7-slide-in { from { opacity: 0; transform: translateY(12px) scale(0.995); } to { opacity: 1; transform: none; } }
@keyframes v7-rise { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }

@media (prefers-reduced-motion: reduce) {
  .v7 .caret { animation: none; }
  .v7 .dot-pulse { animation: none; }
}

@media (prefers-reduced-motion: no-preference) {
  .v7 .dseq.is-live .dslide-on { animation: v7-slide-in 0.42s cubic-bezier(0.22, 1, 0.36, 1) both; }
  .v7 .dseq.is-live .ln-anim { animation: v7-line-in 0.34s ease-out both; }
  .v7 .rise { animation: v7-rise 0.7s cubic-bezier(0.22, 1, 0.36, 1) both; }
}

/**
 * v7 icons.
 *
 * NO `"use client"` in this module, and every icon is its own NAMED function
 * export — never an object of components. A `"use client"` module that exports
 * `export const Icon = { terminal, folder }` and is then read as `<Icon.terminal/>`
