/**
 * v7 product primitives — the actual Nxeon panel, rebuilt as HTML/CSS.
 *
 * Deliberately NOT a `"use client"` module: page.tsx (a Server Component) and
 * DeploySequence / PanelTour (client) both render these, and every export is a
 * plain named function with no hooks, so it works from either side. See
 * icons.tsx for why an object-of-components would not.
 *
 * Every colour comes from a `--env-*` variable, never a literal. Wrap the same
 * markup in `.env-dark` and it is the product; wrap it in `.env-blue` and it
 * draws itself as a blueprint. That single property is what lets the page's
 * dark→light seam show ONE panel clipped across two environments.
 *
 * HONESTY: nothing in here reports a measurement. The metrics panel renders its
 * EMPTY state rather than an invented graph, and every address shown anywhere on
 * this page comes from 203.0.113.0/24 (RFC 5737 TEST-NET-3, the range reserved
 * for documentation) and is labelled as an example.
 */

export type Tone = "ok" | "work" | "idle" | "info";

export type Line = { kind: "cmd" | "out" | "ok" | "note"; k?: string; text: string };

export type FileRow = { dir?: boolean; name: string; size: string; mode: string };
export type NetRow = { label: string; value: string; note?: string };

export const money = (cents: number) => `$${(cents / 100).toFixed(2)}`;

export const ramLabel = (mb: number) => (mb % 1024 === 0 ? `${mb / 1024} GB` : `${mb} MB`);

/* ------------------------------------------------------------------ chrome */

export function Panel({ children, className = "" }: { children: React.ReactNode; className?: string }) {
  return <div className={`pnl ${className}`.trim()}>{children}</div>;
}

export function Dot({ tone = "idle", pulse = false }: { tone?: Tone; pulse?: boolean }) {
  const color =
    tone === "ok"
      ? "var(--env-ok)"
      : tone === "work"
        ? "var(--env-warn)"
        : tone === "info"
          ? "var(--env-accent-2)"
          : "var(--env-tx-4)";
  return <i className={pulse ? "dot dot-pulse" : "dot"} style={{ color }} />;
}

export function Pill({ tone = "idle", children }: { tone?: Tone; children: React.ReactNode }) {
  return (
    <span className={`pill pill-${tone}`}>
      <Dot tone={tone} pulse={tone === "work" || tone === "ok"} />
      {children}
    </span>
  );
}

export function PanelHead({
  name,
  status,
  tone = "idle",
  tabs,
  active,
  mark = true,
}: {
  name: string;
  status: string;
  tone?: Tone;
  tabs?: string[];
  active?: string;
  mark?: boolean;
}) {
  return (
    <div className="pnl-head">
      {mark ? <img className="pnl-mark" src="/nx-mark.png" alt="" width={18} height={18} /> : null}
      <span className="pnl-name">{name}</span>
      <span className="pnl-spacer" />
      {tabs ? (
        <span className="tabs">
          {tabs.map((t) => (
            <span key={t} className={t === active ? "tab tab-on" : "tab"}>
              {t}
            </span>
          ))}
        </span>
      ) : null}
      <Pill tone={tone}>{status}</Pill>
    </div>
  );
}

export function SpecStrip({
  cpu,
  ramMB,
  diskGB,
  bandwidthTB,
}: {
  cpu: number;
  ramMB: number;
  diskGB: number;
  bandwidthTB: number;
}) {
  const cells: [string, string][] = [
    ["vcpu", `${cpu}`],
    ["memory", ramLabel(ramMB)],
    ["nvme disk", `${diskGB} GB`],
    ["transfer", `${bandwidthTB} TB`],
  ];
  return (
    <dl className="spec">
      {cells.map(([k, v]) => (
        <div key={k}>
          <dt>{k}</dt>
          <dd>{v}</dd>
        </div>
      ))}
    </dl>
  );
}

/* ----------------------------------------------------------------- console */

export function ConsoleWell({
  lines,
  caret = false,
  anim = false,
  tall = false,
  runKey,
}: {
  lines: Line[];
  caret?: boolean;
  anim?: boolean;
  tall?: boolean;
  runKey?: string | number;
}) {
  return (
    <div className={tall ? "well well-tall" : "well"} key={runKey}>
      {lines.map((l, i) => (
        <div
          key={`${i}-${l.text}`}
          className={anim ? "ln ln-anim" : "ln"}
          style={anim ? { animationDelay: `${i * 62}ms` } : undefined}
        >
          {l.k ? <span className="ln-k">{l.k}</span> : null}
          <span className={`ln-${l.kind}`}>
            {l.text}
            {caret && i === lines.length - 1 ? <i className="caret" /> : null}
          </span>
        </div>
      ))}
    </div>
  );
}

