/**
 * The metrics surface, rendered as its EMPTY state.
 *
 * This is the one panel where a marketing page is tempted to draw a pretty
 * sawtooth and call it load. There is no customer server behind this page, so
 * any curve here would be fabricated telemetry. Showing the empty state
 * instead is both honest and a stronger product statement: the chrome, the
 * axis, the four series Nxeon actually charts, and a plain note saying the
 * numbers come from your own machine.
 */
export function MetricsPanel() {
  return (
    <div className="metrics">
      <div className="metrics-legend">
        <Pill tone="info">cpu</Pill>
        <Pill tone="idle">memory</Pill>
        <Pill tone="idle">disk i/o</Pill>
        <Pill tone="idle">network</Pill>
