      <div className="metrics-plot">
        <p className="metrics-empty">
          no series — this is the empty state.
          <br />
          your graphs draw from your own server, so there is nothing to plot on a marketing page.
        </p>
      </div>
      <div className="metrics-x">
        <span>-60 min</span>
        <span>-45</span>
        <span>-30</span>
        <span>-15</span>
        <span>now</span>
      </div>
