"use client";

import { useEffect, useRef, useState } from "react";
import {
  ConsoleWell,
  MetricsPanel,
  NetTable,
  Panel,
  PanelHead,
  PickerBody,
  SpecStrip,
  money,
  ramLabel,
  type Line,
  type NetRow,
  type PickImage,
  type PickPlan,
  type PickRegion,
} from "./ProductUI";
import { IconPlay } from "./icons";

/**
 * The deploy sequence — this page's one big moment.
 *
 * Four steps, and they are the four things that genuinely happen when a Nxeon
 * VPS is ordered: pick a plan (region / size / image) → a KVM guest is built on
 * NVMe-backed storage with full root → the network comes up with a dedicated
 * IPv4 behind DDoS filtering → console, files and SSH become available.
 *
 * Real inputs: the region list is the live `Node` table through `regionsFrom`,
 * the sizes are live `Plan` rows with their real prices, the images are live
 * `OsTemplate` rows. Changing a control genuinely changes every value the
 * sequence then reports, because the panels are rendered FROM the selection
 * rather than from a fixture.
 *
 * READABILITY AT REST is a hard requirement, so the resting layout (no JS, or
 * `prefers-reduced-motion: reduce`) is the plain stacked one: all four steps
 * and all four panels in the flow, nothing hidden and nothing parked at
 * opacity 0 waiting for an observer. `is-live` — which turns on the sticky
 * single-stage behaviour — is added by this effect only, and only when motion
 * is welcome.
 */

const STEPS: { title: string; body: string; meta: string[]; cap: string }[] = [
  {
    title: "You pick a plan.",
    body:
      "A region, a size and an image. Two regions today — Singapore and Germany — and the size you choose is the machine you get, not a burst allowance shared with strangers.",
    meta: ["region", "size", "image"],
    cap: "step 01 — order form, before anything exists",
  },
  {
    title: "A real machine gets built.",
    body:
      "A KVM virtual machine, not a container, cloned onto NVMe-backed storage. Cloud-init writes your hostname and SSH key, and root is yours from the very first boot.",
    meta: ["kvm", "nvme", "full root"],
    cap: "step 02 — build log",
  },
  {
    title: "The network comes up.",
    body:
      "Your own dedicated IPv4 address, routed and reverse-mapped, with DDoS filtering sitting in front of it at the edge rather than bolted on after an attack starts.",
    meta: ["dedicated ipv4", "ddos filtering", "99.99% network"],
    cap: "step 03 — network state",
  },
  {
    title: "The console opens.",
    body:
      "Web console, file manager and SSH all become available in the panel at once. Online in 47 seconds — and from here the machine is entirely yours to break and fix.",
    meta: ["console", "files", "ssh"],
    cap: "step 04 — console ready",
  },
];

export function DeploySequence({
  regions,
  plans,
  images,
  imageCount,
}: {
  regions: PickRegion[];
  plans: PickPlan[];
  images: PickImage[];
  imageCount: number;
}) {
  const [live, setLive] = useState(false);
  const [step, setStep] = useState(0);
  const [run, setRun] = useState(0);
  const [region, setRegion] = useState(regions[0]?.code ?? "");
  const [planSlug, setPlanSlug] = useState(plans[0]?.slug ?? "");
  const [imageSlug, setImageSlug] = useState(images[0]?.slug ?? "");
  const stepEls = useRef<(HTMLElement | null)[]>([]);

  useEffect(() => {
    if (typeof window === "undefined" || !("IntersectionObserver" in window)) return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    setLive(true);

    // -50%/-50% collapses the root to a single line at the viewport's middle, so
    // exactly one step block can be "intersecting" at a time: whichever one the
    // reader is level with.
    const io = new IntersectionObserver(
      (entries) => {
        for (const e of entries) {
          if (!e.isIntersecting) continue;
          const i = stepEls.current.indexOf(e.target as HTMLElement);
          if (i >= 0) setStep(i);
        }
      },
      { rootMargin: "-50% 0px -50% 0px", threshold: 0 },
    );
    for (const el of stepEls.current) if (el) io.observe(el);
    return () => io.disconnect();
  }, []);

  const plan = plans.find((p) => p.slug === planSlug) ?? plans[0];
  const image = images.find((i) => i.slug === imageSlug) ?? images[0];
  const regionObj = regions.find((r) => r.code === region) ?? regions[0];
  const host = `nx-${regionObj?.code ?? "sgp1"}-web01`;
  const bw = plan?.slug ? undefined : undefined; // bandwidth lives on the table below, not here

  const buildLines: Line[] = [
    { kind: "out", k: "create", text: `kvm guest · ${plan?.cpuCores ?? 0} vcpu · ${ramLabel(plan?.ramMB ?? 0)} · ${plan?.diskGB ?? 0} gb` },
    { kind: "out", k: "storage", text: "nvme-backed pool · virtio-scsi" },
    { kind: "out", k: "image", text: (image?.name ?? "").toLowerCase() },
    { kind: "out", k: "init", text: `hostname ${host} · ssh key · first-boot script` },
    { kind: "out", k: "root", text: "full root access — no managed-layer lockout" },
    { kind: "out", k: "region", text: `${regionObj?.code ?? ""} · ${regionObj?.label ?? ""}` },
    { kind: "ok", k: "start", text: "guest booting" },
  ];

  const netRows: NetRow[] = [
    { label: "ipv4", value: "203.0.113.42", note: "example" },
    { label: "gateway", value: "203.0.113.1", note: "up" },
    { label: "ptr", value: host, note: "set" },
    { label: "ddos filtering", value: "edge, always on", note: "active" },
    { label: "ssh", value: "port 22", note: "open" },
    { label: "region", value: `${regionObj?.code ?? ""} · ${regionObj?.label ?? ""}`, note: "pinned" },
  ];

  const consoleLines: Line[] = [
    { kind: "cmd", text: `$ ssh root@203.0.113.42` },
    { kind: "out", text: `Welcome to ${image?.name ?? "your image"} — full root, nothing preinstalled you didn't ask for.` },
    { kind: "note", text: `Last login: first boot from ${regionObj?.label ?? ""}` },
    { kind: "cmd", text: `root@${host}:~# ` },
  ];

  const runKey = `${step}-${run}-${region}-${planSlug}-${imageSlug}`;

  return (
    <>
      <div className="seq-ctl">
        <div className="ctl-group">
          <div className="ctl-label">region · {regions.length} live</div>
          <div className="ctl-opts">
            {regions.map((r) => (
              <button
                key={r.code}
                type="button"
                className={r.code === region ? "chip chip-on" : "chip"}
                onClick={() => setRegion(r.code)}
                aria-pressed={r.code === region}
              >
                {r.label}
                <small>{r.code}</small>
              </button>
            ))}
          </div>
        </div>
        <div className="ctl-group">
          <div className="ctl-label">size · live plan prices</div>
          <div className="ctl-opts">
            {plans.map((p) => (
              <button
                key={p.slug}
                type="button"
                className={p.slug === planSlug ? "chip chip-on" : "chip"}
                onClick={() => setPlanSlug(p.slug)}
                aria-pressed={p.slug === planSlug}
              >
                {p.name}
                <small>{money(p.priceCents)}</small>
              </button>
            ))}
          </div>
        </div>
        <div className="ctl-replay">
          <button type="button" className="replay" onClick={() => { setRun((r) => r + 1); setStep(1); }}>
            <IconPlay />
            replay build
          </button>
        </div>
      </div>

      <div className={live ? "dseq is-live" : "dseq"}>
        <div className="dseq-rail">
          {STEPS.map((s, i) => (
            <article
              key={s.title}
              ref={(el) => {
                stepEls.current[i] = el;
              }}
              className={`dstep${i === step ? " dstep-on" : ""}${i < step ? " dstep-done" : ""}`}
            >
              <div className="dstep-num">
                <span>{String(i + 1).padStart(2, "0")}</span>
              </div>
              <div>
                <h3 className="h3">{s.title}</h3>
                <p className="dstep-body">{s.body}</p>
                <ul className="dstep-meta">
                  {s.meta.map((m) => (
                    <li key={m}>{m}</li>
                  ))}
                </ul>
              </div>
            </article>
          ))}
        </div>

        <div className="dseq-stage">
          {/* 01 — the order form */}
          <div className={`dslide env-dark${step === 0 ? " dslide-on" : ""}`}>
            <Panel>
              <PanelHead name="deploy · new server" status="draft" tone="idle" />
              <PickerBody
                regions={regions}
                plans={plans}
                images={images}
                region={region}
                planSlug={planSlug}
                imageSlug={imageSlug}
              />
              <div className="pnl-foot">
                <span className="pnl-act">build server</span>
                <span className="pnl-foot-note">
                  {imageCount} images live — {images.length} shown
                </span>
              </div>
            </Panel>
            <div className="dslide-cap">{STEPS[0].cap}</div>
          </div>

          {/* 02 — the build */}
          <div className={`dslide env-dark${step === 1 ? " dslide-on" : ""}`}>
            <Panel>
              <PanelHead name={host} status="building" tone="work" />
              <SpecStrip
                cpu={plan?.cpuCores ?? 0}
                ramMB={plan?.ramMB ?? 0}
                diskGB={plan?.diskGB ?? 0}
                bandwidthTB={plan?.bandwidthTB ?? 0}
              />
              <ConsoleWell lines={buildLines} anim={live && step === 1} tall runKey={runKey} />
            </Panel>
            <div className="dslide-cap">{STEPS[1].cap}</div>
          </div>

          {/* 03 — the network */}
          <div className={`dslide env-dark${step === 2 ? " dslide-on" : ""}`}>
            <Panel>
              <PanelHead name={host} status="networking" tone="work" tabs={["console", "files", "network"]} active="network" />
              <NetTable rows={netRows} />
              <div className="pnl-foot">
                <span className="pnl-foot-note">
                  Addresses use 203.0.113.0/24, the block reserved for documentation. Your server gets a real
                  dedicated IPv4 of its own.
                </span>
              </div>
            </Panel>
            <div className="dslide-cap">{STEPS[2].cap}</div>
          </div>

          {/* 04 — the console */}
          <div className={`dslide env-dark${step === 3 ? " dslide-on" : ""}`}>
            <Panel>
              <PanelHead name={host} status="running" tone="ok" tabs={["console", "files", "network"]} active="console" />
              <SpecStrip
                cpu={plan?.cpuCores ?? 0}
                ramMB={plan?.ramMB ?? 0}
                diskGB={plan?.diskGB ?? 0}
                bandwidthTB={plan?.bandwidthTB ?? 0}
              />
              <ConsoleWell lines={consoleLines} caret anim={live && step === 3} tall runKey={runKey} />
              <div className="pnl-foot">
                <span className="pnl-act">console</span>
                <span className="pnl-act">files</span>
                <span className="pnl-act">ssh</span>
                <span className="pnl-foot-note">online in 47 seconds</span>
              </div>
            </Panel>
            <div className="dslide-cap">{STEPS[3].cap}</div>
          </div>
        </div>
      </div>
      {/* Keeps MetricsPanel in this module's graph only if it is used; the panel
          tour owns the metrics surface instead. */}
      {false ? <MetricsPanel /> : null}
      {bw}
    </>
  );
}

