input.content:
"use client";

import { useState } from "react";
import {
  ConsoleWell,
  FileTable,
  MetricsPanel,
  NetTable,
  Panel,
  PanelHead,
  SpecStrip,
  type FileRow,
  type Line,
  type NetRow,
} from "./ProductUI";

/**
 * The light half's product tour.
 *
 * The panel itself stays DARK here, mounted on paper like a plate in a manual,
 * because the portal is a dark product and recolouring it for the marketing
 * page would be a claim about a light theme that does not exist. The controls
 * around it are paper — they belong to this page, not to the product — which is
 * exactly the division the whole concept rests on.
 *
 * The four surfaces are the four the panel really has. Metrics deliberately
 * renders its EMPTY state (see ProductUI.MetricsPanel): there is no customer
 * server behind a marketing page, so there is nothing legitimate to plot.
 */

const TABS = ["console", "files", "network", "metrics"] as const;
type Tab = (typeof TABS)[number];

const CAPTIONS: Record<Tab, string> = {
  console:
    "An example session. The console is a real shell on your machine — no restricted command list, no managed layer between you and the OS.",
  files:
    "The file manager reads the actual filesystem. Same files over SFTP, same files over SSH; edit in the browser when that is faster.",
  network:
    "Your dedicated IPv4, its routing and the edge filter in front of it. Values shown come from 203.0.113.0/24, the block reserved for documentation.",
  metrics:
    "Shown as the empty state on purpose: your graphs draw from your own server, so a marketing page has nothing honest to plot here.",
};

export function PanelTour({
  host,
  planName,
  cpuCores,
  ramMB,
  diskGB,
  bandwidthTB,
  imageName,
  regionLabel,
  regionCode,
}: {
  host: string;
  planName: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  bandwidthTB: number;
  imageName: string;
  regionLabel: string;
  regionCode: string;
}) {
  const [tab, setTab] = useState<Tab>("console");

  const consoleLines: Line[] = [
    { kind: "cmd", text: "$ apt-get install -y nginx" },
    { kind: "out", text: "Setting up nginx (1.24.0) ..." },
    { kind: "cmd", text: "$ systemctl enable --now nginx" },
    { kind: "cmd", text: "$ curl -sI localhost | head -1" },
    { kind: "ok", text: "HTTP/1.1 200 OK" },
    { kind: "cmd", text: `root@${host}:~# ` },
  ];

  const files: FileRow[] = [
    { dir: true, name: "etc/nginx/", size: "—", mode: "drwxr-xr-x" },
    { dir: true, name: "var/www/site/", size: "—", mode: "drwxr-xr-x" },
    { name: "docker-compose.yml", size: "1.4 kB", mode: "-rw-r--r--" },
    { name: ".env", size: "312 B", mode: "-rw-------" },
    { name: "backup-nightly.sh", size: "2.0 kB", mode: "-rwxr-xr-x" },
  ];

  const net: NetRow[] = [
    { label: "ipv4", value: "203.0.113.42", note: "example" },
    { label: "ptr", value: host, note: "set" },
    { label: "ddos filtering", value: "edge, always on", note: "active" },
    { label: "firewall", value: "22/tcp, 80/tcp, 443/tcp", note: "open" },
    { label: "region", value: `${regionCode} · ${regionLabel}`, note: "pinned" },
  ];

  return (
    <div className="island">
      <div className="island-mount">
        <div className="island-bar">
          <span className="ib-label">panel</span>
          {TABS.map((t) => (
            <button
              key={t}
              type="button"
              className={t === tab ? "ptab ptab-on" : "ptab"}
              onClick={() => setTab(t)}
              aria-pressed={t === tab}
            >
              {t}
            </button>
          ))}
        </div>
        <div className="env-dark">
          <Panel>
            <PanelHead
              name={`${host} · ${planName}`}
              status={tab === "metrics" ? "no data" : "running"}
              tone={tab === "metrics" ? "idle" : "ok"}
              tabs={["console", "files", "network", "metrics"]}
              active={tab}
            />
            {tab === "console" ? (
              <>
                <SpecStrip cpu={cpuCores} ramMB={ramMB} diskGB={diskGB} bandwidthTB={bandwidthTB} />
                <ConsoleWell lines={consoleLines} caret tall />
              </>
            ) : null}
            {tab === "files" ? (
              <>
                <FileTable rows={files} />
                <div className="pnl-foot">
                  <span className="pnl-act">upload</span>
                  <span className="pnl-act">new file</span>
                  <span className="pnl-foot-note">sftp + ssh reach the same paths</span>
                </div>
              </>
            ) : null}
            {tab === "network" ? (
              <>
                <NetTable rows={net} />
                <div className="pnl-foot">
                  <span className="pnl-foot-note">{imageName} · full root · 99.99% network</span>
                </div>
              </>
            ) : null}
            {tab === "metrics" ? <MetricsPanel /> : null}
          </Panel>
        </div>
      </div>
      <p className="island-cap">{CAPTIONS[tab]}</p>
    </div>
  );
}

