import type { Metadata } from "next";
import { Chivo, Martian_Mono } from "next/font/google";
import "./v7.css";

/**
 * v7 "Console" shell.
 *
 * Isolated from (marketing), from the portal and from the other concept routes:
 * its own wrapper class, its own stylesheet, its own two typefaces. Nothing in
 * here touches a shared file.
 *
 * TYPE — two faces, two jobs, and neither is Inter, Geist or Space Grotesk:
 *
 *  · CHIVO carries the human voice: headlines at 900, sub-heads at 700, prose at
 *    400. An industrial grotesk with real weight at display size and a proper
 *    text weight underneath, so one family can hold both the cinematic dark hero
 *    and the paper half's reading copy.
 *
 *  · MARTIAN MONO is the machine voice, and it is the page's signature: console
 *    output, build logs, step numerals, spec values, prices, region codes, every
 *    eyebrow. It is unusually WIDE for a mono, which makes small mono text read
 *    as engineered rather than as decorative "code font" — and it is the one
 *    element that carries identically across the dark→light seam, so the two
 *    environments are audibly the same page.
 */
const sans = Chivo({
  subsets: ["latin"],
  weight: ["400", "500", "600", "700", "900"],
  variable: "--font-v7-sans",
  display: "swap",
});

const mono = Martian_Mono({
  subsets: ["latin"],
  weight: ["400", "500", "700"],
  variable: "--font-v7-mono",
  display: "swap",
});

export const metadata: Metadata = {
  title: "Nxeon — here is the thing you're buying",
  description:
    "A concept homepage whose subject is the product: the panel, the console, the deploy sequence. KVM VPS on NVMe with full root, a dedicated IPv4 and DDoS filtering, in Singapore or Germany.",
  robots: { index: false, follow: false },
};

export default function V7Layout({ children }: { children: React.ReactNode }) {
  return <div className={`v7 ${sans.variable} ${mono.variable}`}>{children}</div>;
}

