const { chromium } = require("/opt/nxeon/node_modules/playwright");
const OUT = "/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad";
(async () => {
  const b = await chromium.launch();
  const p = await b.newPage({ viewport: { width: 1440, height: 950 } });
  const errs = [];
  p.on("pageerror", (e) => errs.push(String(e).slice(0, 200)));
  await p.goto("http://127.0.0.1:4098/newwebsitev7", { waitUntil: "networkidle", timeout: 120000 });
  const H = await p.evaluate(() => document.body.scrollHeight);
  for (let y = 0; y < H; y += 600) { await p.evaluate((y) => window.scrollTo(0, y), y); await p.waitForTimeout(120); }
  await p.evaluate(() => window.scrollTo(0, 0)); await p.waitForTimeout(600);
  const broken = await p.evaluate(() => [...document.images].filter(i => !i.complete || i.naturalWidth === 0).map(i => i.src));
  const d = await p.evaluate(() => ({ sw: document.documentElement.scrollWidth, cw: document.documentElement.clientWidth, h: document.body.scrollHeight }));
  console.log("FINAL dims", JSON.stringify(d), "broken", JSON.stringify(broken), "errs", JSON.stringify(errs));
  await p.evaluate(() => window.scrollTo(0, document.querySelector(".v7 .seam").getBoundingClientRect().top + window.scrollY - 40));
  await p.waitForTimeout(400);
  await p.screenshot({ path: `${OUT}/v7-FINAL-seam.png` });
  await b.close();
})().catch(e => { console.error("FAIL", e.message); process.exit(1); });
